import java.util.Scanner;

public class ParkingTicket {
    String vehicle;         // registration number
    int hours;              // hours parked
    int fee;                // amount to pay in rupees

    void accept() {
        Scanner sc = new Scanner(System.in);
        vehicle = sc.next();
        hours = sc.nextInt();
    }

    void calculate() {
        fee = 20;                           // first hour
        if (hours > 1)
            fee = fee + (hours - 1) * 15;   // each later hour
        if (fee > 100)
            fee = 100;                      // upper limit
    }

    void display() {
        System.out.println("Vehicle : " + vehicle);
        System.out.println("Hours   : " + hours);
        System.out.println("Fee     : Rs. " + fee);
    }

    public static void main(String[] args) {
        ParkingTicket t = new ParkingTicket();
        t.accept();
        t.calculate();
        t.display();
    }
}
```

