import java.util.Scanner;

public class LibraryCard {
    int cardNo;             // card number
    String holder;          // name of the member
    int issued;             // books held at present
    int limit = 3;          // most books allowed at a time

    void accept() {
        Scanner sc = new Scanner(System.in);
        cardNo = sc.nextInt();
        holder = sc.next();
    }

    void issue(int n) {
        if (issued + n <= limit) {
            issued = issued + n;
            System.out.println(n + " book(s) issued");
        } else {
            System.out.println("Limit of " + limit + " exceeded, nothing issued");
        }
    }

    void giveBack(int n) {
        if (n <= issued)
            issued = issued - n;
    }

    void display() {
        System.out.println("Card " + cardNo + " of " + holder + " holds " + issued + " book(s)");
    }

    public static void main(String[] args) {
        LibraryCard c = new LibraryCard();
        c.accept();
        c.issue(2);
        c.issue(2);
        c.giveBack(1);
        c.display();
    }
}
```

**Sample input** (card number, then holder): `4412 Farhan`

**Output**

```text
2 book(s) issued
Limit of 3 exceeded, nothing issued
Card 4412 of Farhan holds 1 book(s)
```

