import java.util.Scanner;

public class Bulb {
    int watts;              // power rating of the bulb
    double hoursPerDay;     // hours it is on each day
    double rate = 7.5;      // rupees per unit of electricity

    void accept() {
        Scanner sc = new Scanner(System.in);
        watts = sc.nextInt();
        hoursPerDay = sc.nextDouble();
    }

    double units(int days) {
        return watts * hoursPerDay * days / 1000;
    }

    double bill(int days) {
        return units(days) * rate;
    }

    void display(int days) {
        System.out.println("Units used in " + days + " days: " + units(days));
        System.out.println("Bill amount: Rs. " + bill(days));
    }

    public static void main(String[] args) {
        Bulb b = new Bulb();
        b.accept();
        b.display(30);
    }
}
```

