import java.util.Scanner;

public class Carton {
    int length, breadth, height;    // sizes in centimetres
    int volume;                     // in cubic centimetres
    int area;                       // total outer surface area

    void accept() {
        Scanner sc = new Scanner(System.in);
        length = sc.nextInt();
        breadth = sc.nextInt();
        height = sc.nextInt();
    }

    void compute() {
        volume = length * breadth * height;
        area = 2 * (length * breadth + breadth * height + length * height);
    }

    void display() {
        System.out.println("Volume       : " + volume + " cubic cm");
        System.out.println("Surface area : " + area + " square cm");
    }

    public static void main(String[] args) {
        Carton c = new Carton();
        c.accept();
        c.compute();
        c.display();
    }
}
```

