import java.util.Scanner;

public class Teacher {
    String name;                    // name of the teacher
    double basic, da, hra, pf, net; // pay components in rupees

    void accept() {
        Scanner sc = new Scanner(System.in);
        name = sc.next();
        basic = sc.nextDouble();
    }

    void compute() {
        da = basic * 35 / 100;
        hra = basic * 20 / 100;
        pf = basic * 10 / 100;
        net = basic + da + hra - pf;
    }

    void display() {
        System.out.println("Teacher    : " + name);
        System.out.println("Allowances : " + (da + hra));
        System.out.println("Deduction  : " + pf);
        System.out.println("Net salary : " + net);
    }

    public static void main(String[] args) {
        Teacher t = new Teacher();
        t.accept();
        t.compute();
        t.display();
    }
}
```

